public Task<Value> LoadAsync(string key, CancellationToken ct) =>
    _inflight.GetOrAdd(key, k => new Lazy<Task<Value>>(async () =>
    {
        try { return await _source.ReadAsync(k, ct).ConfigureAwait(false); }
        finally { _inflight.TryRemove(k, out _); }   // forget when the flight ends
